import {downloadInfo, downloadDelete, addNums} from "@/api/assets/devStandingBook";
import {mapGetters} from "vuex";

export default {
  props: ['isShow'],
  data() {
    return {
      tableData: null,
      tableLoading: false,

      page: {
        currentPage: 1,
        pageSize: 20,
        total: 0,
      },
    };
  },
  computed: {
    ...mapGetters(["userDetail"]),
    isVisible: {
      get() {
        return this.isShow
      },
      set(val) {
        this.$emit("update:isShow", val)
      }
    }

  },
  mounted() {
    this.getList();
  },
  methods: {
    getList() {
      this.tableLoading = true;
      downloadInfo(this.page.currentPage, this.page.pageSize, {
        userId: this.userDetail.userId
      }).then(res => {
        this.page.total = res.data.total;
        this.tableData = res.data.records;
      }).finally(() => {
        this.tableLoading = false;
      });
    },
    Nindex(index) {
      return index + 1 + (this.page.currentPage - 1) * this.page.pageSize;
    },
    handleDowload(row) {
      if (row.status == '1') {
        //导出中
        this.$message.warning('文件导出中，请耐心等待');
        return;
      }
      if (row.status == '3') {
        //重试
        if (row.exportJson) {
          let params = JSON.parse(row.exportJson);
          if (params) {
            let fileName = `设备台账${this.getTodayTime()}.xlsx`;
            row.status = '1';
            this.download("/api/idevelop-device/hardwarebasic/cmdb/download", {...params, bs: '1', fileId: row.id}, fileName, '下载中，请稍后', false, false, () => {
              this.getList();
            });
          }
        }
        return;
      }
      if (row.link && row.link != '') {
        //走浏览器文件下载
        let fileName = row.fileName ? row.fileName : `设备台账${this.getTodayTime()}.xlsx`;
        const x = new window.XMLHttpRequest();
        x.open('GET', row.link, true);
        x.responseType = 'blob';
        x.onload = () => {
          const url2 = window.URL.createObjectURL(x.response);
          const a = document.createElement('a');
          a.href = url2;
          a.download = fileName;
          a.click();
          a.style.display = 'none';
          const timer = setTimeout(() => {
            a.remove();

            //释放blob对象
            URL.revokeObjectURL(url2);
            clearTimeout(timer);
          }, 1000);
        };
        x.send();

        //统计下载次数

        addNums({id: row.id}).then(res => {
          row.nums++;

          this.$emit('refreshAllNum');
        })
      }
    },

    handleDelete(row) {
      let ids = [];
      if (row == null) {
        //删除选中
        if (this.$refs.dataTable.selection.length === 0) {
          this.$message.warning("请选择至少一条数据");
          return;
        }
        ids = this.$refs.dataTable.selection.map(a => {
          return a.id;
        })
      } else {
        ids.push(row.id)
      }

      this.$confirm("确定将选择数据删除?", {
        confirmButtonText: "确定",
        cancelButtonText: "取消",
        type: "warning"
      }).then(() => {
        return downloadDelete(ids);
      }).then(() => {
        this.getList();
        this.$message({
          type: "success",
          message: "删除成功!"
        });
      });
    },
    getStatusColor(status) {
      if (status == '1') {
        return '#FCC628';
      } else if (status == '2') {
        return '#299B48';
      } else if (status == '3') {
        return '#E74133';
      }
      return '';
    },
    getStatusText(status) {
      if (status == '1') {
        return '导出中...';
      } else if (status == '2') {
        return '导出成功';
      } else if (status == '3') {
        return '导出失败';
      }
      return '';
    },
    getDBtnText(status) {
      if (status == '1') {
        return '正在导出...'
      } else if (status == '2') {
        return '下载'
      } else if (status == '3') {
        return '重试'
      }
      return null;
    },
    getTodayTime(day = 0) {
      let date = new Date()
      date.setDate((new Date().getDate() + day));
      let y = date.getFullYear();
      let m = date.getMonth() + 1;
      let d = date.getDate();
      let hour = date.getHours();
      let min = date.getMinutes();

      m = (m >= 10) ? m : "0" + m;
      d = (d >= 10) ? d : "0" + d;

      hour = (hour >= 10) ? hour : "0" + hour;
      min = (min >= 10) ? min : "0" + min;

      let timeStr = date.getTime().toString();
      let tRand = timeStr.substring(timeStr.length - 2, timeStr.length);

      return `${y}${m}${d}${hour}${min}${tRand}`;
    },
  },
}
